public static int height(BinNode<Integer> t) {
    if (t == null) {
        return -1;
    }
    return 1 + Math.max(height(t.getLeft()), height(t.getRight()));
}

public static int countAtLevel(BinNode<Integer> t, int k) {
    if (t == null) {
        return 0;
    }
    if (k == 0) {
        return 1;
    }
    return countAtLevel(t.getLeft(), k - 1) + countAtLevel(t.getRight(), k - 1);
}

